//! `linux::errno!`: errno names. Numbers differ between architectures, so the
//! parser returns the canonical name and the runtime crate supplies the number.

use crate::suggest;
use proc_macro2::{Ident, Span, TokenStream};
use quote::{quote, quote_spanned};

// Generated by oracle/errno_tables.py from libc 0.2.191 (see that file); every
// Linux family has every name, ordered by generic number, aliases last.
